//! The FreeLunch Griffin system as a checked-in fixture, read back under a weighted order.
//!
//! The fixtures under `research/griffin/` are generated by
//! `tools/check-griffin-reconstruction.py --build-system R --fixture PATH`, which builds the
//! system symbolically from the published Griffin parameters over the Appendix B bypass line that
//! `docs/research/griffin-freelunch.md` §1.2 recovers from the published witnesses. They are
//! checked in rather than rebuilt because `r = 5` costs 15 s in CPython and nothing here depends
//! on rebuilding it; the generator and the exact command are recorded in the file's header, so a
//! reader can regenerate and diff.
//!
//! What this module is for is the one claim a unit test cannot make on its own: that the weighted
//! order is **the** order the attack uses, on an instance whose solutions are published. Under the
//! weight vector Construction 1 derives, each modelling equation `p_i = x_i^α − q_i` has
//! `wt(x_i^α) = wt(LM(q_i))` **exactly** — the pure power and the tail tie on weighted degree — so
//! which one leads is decided by the tie-break alone, and the quotient dimension `D_I` the paper
//! publishes comes out only if that tie-break is FreeLunch's.

use crate::{
    fields::KnownOrder, FiniteField, Monomial, MonomialOrder, MultivariatePolynomial,
    WeightedOrderError, WeightedTieBreak,
};

/// The prime of the FreeLunch Griffin instance `(t, α) = (12, 3)`, 55 bits.
pub const FREELUNCH_PRIME: u64 = 28407454060060787;

/// The `r = 4` system: 2 variables, weight vector `(1, 7)`, `D_I = 441`.
pub const FREELUNCH_R4: &str = include_str!("../../../research/griffin/freelunch-r4.txt");

/// The `r = 5` system: 3 variables, weight vector `(1, 7, 49)`, `D_I = 9261`, and the two
/// published CICO witnesses at that round count.
pub const FREELUNCH_R5: &str = include_str!("../../../research/griffin/freelunch-r5.txt");

/// A FreeLunch system together with the order it is a Gröbner basis under.
#[derive(Clone, Debug)]
pub struct FreeLunchSystem<const N: usize, F: FiniteField> {
    /// Rounds of the Griffin permutation the system models.
    pub rounds: usize,

    /// The weight vector of `≺_G`, derived by Construction 1 and cleared of denominators.
    pub weights: Vec<u32>,

    /// `α_0 = deg_{x_0} g`, which with `D_H = α^{N-1}` gives `D_I = α_0 · D_H`.
    pub alpha0: u32,

    /// The ideal degree `D_I` the generator reported, for comparison against a computed one.
    pub quotient_dimension: usize,

    /// The published CICO witnesses, in the system's variables. Empty at round counts the
    /// FreeLunch appendix publishes no solution for.
    pub witnesses: Vec<[F; N]>,

    /// `p_1, …, p_{N-1}, g`, in that order.
    pub generators: Vec<MultivariatePolynomial<N, F>>,
}

impl<const N: usize, F: KnownOrder> FreeLunchSystem<N, F> {
    /// Parse one of the `research/griffin/` fixtures.
    ///
    /// # Errors
    /// [`FixtureError`] on a malformed line, a variable count other than `N`, or a weight vector
    /// the order refuses.
    pub fn parse(text: &str) -> Result<Self, FixtureError> {
        let mut rounds = None;
        let mut prime = None;
        let mut variables = None;
        let mut weights: Vec<u32> = Vec::new();
        let mut alpha0 = None;
        let mut quotient_dimension = None;
        let mut witnesses = Vec::new();
        let mut generators: Vec<MultivariatePolynomial<N, F>> = Vec::new();
        let mut terms: Vec<(Monomial<N>, F)> = Vec::new();
        let mut open = false;

        let flush = |open: &mut bool,
                     terms: &mut Vec<(Monomial<N>, F)>,
                     generators: &mut Vec<MultivariatePolynomial<N, F>>| {
            if *open {
                generators.push(MultivariatePolynomial::new(terms));
                terms.clear();
                *open = false;
            }
        };

        for (number, line) in text.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let at = number + 1;
            let malformed = || FixtureError::Malformed { line: at };
            let fields: Vec<&str> = line.split_whitespace().collect();
            match fields[0] {
                "rounds" => rounds = Some(parse_usize(fields.get(1), at)?),
                "prime" => prime = Some(parse_u64(fields.get(1), at)?),
                "variables" => {
                    // Checked as soon as it is read, so a fixture parsed at the wrong `N` says
                    // so rather than failing on the first line whose field count disagrees.
                    let fixture = parse_usize(fields.get(1), at)?;
                    if fixture != N {
                        return Err(FixtureError::VariableCount {
                            fixture,
                            expected: N,
                        });
                    }
                    variables = Some(fixture);
                }
                "alpha0" => alpha0 = Some(parse_usize(fields.get(1), at)? as u32),
                "quotient_dimension" => quotient_dimension = Some(parse_usize(fields.get(1), at)?),
                "weights" => {
                    weights = fields[1..]
                        .iter()
                        .map(|w| w.parse::<u32>().map_err(|_| malformed()))
                        .collect::<Result<_, _>>()?;
                }
                "witness" => {
                    if fields.len() != N + 1 {
                        return Err(malformed());
                    }
                    let mut point = [F::zero(); N];
                    for (i, field) in fields[1..].iter().enumerate() {
                        point[i] = F::new(field.parse::<u64>().map_err(|_| malformed())?);
                    }
                    witnesses.push(point);
                }
                "polynomial" => {
                    flush(&mut open, &mut terms, &mut generators);
                    open = true;
                }
                _ => {
                    // A term: N exponents then the coefficient.
                    if fields.len() != N + 1 || !open {
                        return Err(malformed());
                    }
                    let mut exponents = [0u32; N];
                    for (i, field) in fields[..N].iter().enumerate() {
                        exponents[i] = field.parse::<u32>().map_err(|_| malformed())?;
                    }
                    let coefficient = F::new(fields[N].parse::<u64>().map_err(|_| malformed())?);
                    terms.push((Monomial::new(&exponents), coefficient));
                }
            }
        }
        flush(&mut open, &mut terms, &mut generators);

        variables.ok_or(FixtureError::MissingHeader)?;
        if weights.len() != N {
            return Err(FixtureError::VariableCount {
                fixture: weights.len(),
                expected: N,
            });
        }
        let prime = prime.ok_or(FixtureError::MissingHeader)?;
        if F::characteristic_u128() != Some(prime as u128) {
            return Err(FixtureError::Characteristic {
                fixture: prime,
                field: F::characteristic_u128(),
            });
        }

        Ok(Self {
            rounds: rounds.ok_or(FixtureError::MissingHeader)?,
            weights,
            alpha0: alpha0.ok_or(FixtureError::MissingHeader)?,
            quotient_dimension: quotient_dimension.ok_or(FixtureError::MissingHeader)?,
            witnesses,
            generators,
        })
    }

    /// `≺_G`: the fixture's weight vector under FreeLunch's tie-break.
    pub fn order(&self) -> Result<MonomialOrder, WeightedOrderError> {
        MonomialOrder::weighted(&self.weights, WeightedTieBreak::LastVariableFirst)
    }
}

fn parse_usize(field: Option<&&str>, line: usize) -> Result<usize, FixtureError> {
    field
        .ok_or(FixtureError::Malformed { line })?
        .parse::<usize>()
        .map_err(|_| FixtureError::Malformed { line })
}

fn parse_u64(field: Option<&&str>, line: usize) -> Result<u64, FixtureError> {
    field
        .ok_or(FixtureError::Malformed { line })?
        .parse::<u64>()
        .map_err(|_| FixtureError::Malformed { line })
}

/// Why a `research/griffin/` fixture could not be read.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum FixtureError {
    /// A line the format does not describe.
    Malformed { line: usize },

    /// A header directive the reader needs is absent.
    MissingHeader,

    /// The fixture's variable count is not the `N` it was parsed at.
    VariableCount { fixture: usize, expected: usize },

    /// The fixture's prime is not the field's characteristic, so every coefficient would be
    /// reduced into the wrong field.
    Characteristic { fixture: u64, field: Option<u128> },
}

impl std::fmt::Display for FixtureError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Malformed { line } => write!(f, "line {} is not a directive or a term", line),
            Self::MissingHeader => write!(f, "the fixture is missing a header directive"),
            Self::VariableCount { fixture, expected } => write!(
                f,
                "the fixture has {} variables but was parsed at {}",
                fixture, expected
            ),
            Self::Characteristic { fixture, field } => write!(
                f,
                "the fixture is over F_{} but the field has characteristic {:?}",
                fixture, field
            ),
        }
    }
}

impl std::error::Error for FixtureError {}

#[cfg(test)]
mod tests {
    use super::{FreeLunchSystem, FREELUNCH_PRIME, FREELUNCH_R4, FREELUNCH_R5};
    use crate::{
        fields::PrimeFieldElement64,
        grobner::{fglm::QuotientBasis, leading_monomials_are_pairwise_coprime},
        FiniteField, Monomial, MonomialOrder, WeightedTieBreak, Zero,
    };

    type F = PrimeFieldElement64<FREELUNCH_PRIME>;

    /// The `r = 5` fixture carries the weight vector `(1, 7, 49)` Construction 1 derives.
    ///
    /// `docs/research/griffin-freelunch.md` §2.1: over the recovered bypass line the
    /// `wt(x_i) = 7^{i-1}/3` denominators clear and the weight vector is these integers.
    #[test]
    fn test_the_weight_vector_at_r5_is_one_seven_forty_nine() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        assert_eq!(system.rounds, 5);
        assert_eq!(system.weights, vec![1, 7, 49]);
        assert_eq!(system.alpha0, 1029);
        assert_eq!(system.generators.len(), 3);

        let r4 = FreeLunchSystem::<2, F>::parse(FREELUNCH_R4).unwrap();
        assert_eq!(r4.weights, vec![1, 7]);
        assert_eq!(r4.alpha0, 147);
    }

    /// Under `≺_G` the leading monomials are the pure powers `x_1^3, x_2^3, x_0^{1029}`.
    ///
    /// Pairwise coprime, so the input system is a Gröbner basis by Buchberger's first criterion
    /// with no reduction performed — the fact that removes F4 from the attack.
    #[test]
    fn test_the_r5_system_is_a_grobner_basis_under_the_weighted_order() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        let order = system.order().unwrap();
        let leading: Vec<Monomial<3>> = system
            .generators
            .iter()
            .map(|f| f.leading_monomial(order))
            .collect();
        assert_eq!(
            leading,
            vec![
                Monomial::<3>::new(&[0, 3, 0]),
                Monomial::<3>::new(&[0, 0, 3]),
                Monomial::<3>::new(&[1029, 0, 0]),
            ]
        );
        assert!(leading_monomials_are_pairwise_coprime(
            &system.generators,
            order
        ));
    }

    /// The weighted order's tie-break is what selects those leading monomials, not the grading.
    ///
    /// Construction 1 makes `wt(x_i^3) = wt(LM(q_i))` exactly, so `p_1`'s two candidate leading
    /// monomials `x_1^3` and `x_0^21` have the *same* weighted degree 21 and grevlex's tie-break
    /// picks the other one. Getting the tie-break wrong therefore does not fail loudly — it
    /// returns a different leading ideal from the same polynomials, which is the failure this
    /// whole capability had to be written against.
    #[test]
    fn test_the_tie_break_decides_the_leading_monomials() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        let freelunch = system.order().unwrap();
        let grevlex_tie_break =
            MonomialOrder::weighted(&system.weights, WeightedTieBreak::ReverseLexicographic)
                .unwrap();

        // Same weighted degree on both candidates, so the grading alone decides nothing.
        let x1_cubed = Monomial::<3>::new(&[0, 3, 0]);
        let x0_21 = Monomial::<3>::new(&[21, 0, 0]);
        let MonomialOrder::Weighted(weighted) = freelunch else {
            panic!("expected a weighted order");
        };
        assert_eq!(
            weighted.weighted_degree(&x1_cubed),
            weighted.weighted_degree(&x0_21)
        );
        assert!(system.generators[0].terms().contains_key(&x1_cubed));
        assert!(system.generators[0].terms().contains_key(&x0_21));

        assert_eq!(
            system.generators[0].leading_monomial(freelunch),
            x1_cubed,
            "FreeLunch's tie-break must put the pure power on top"
        );
        assert_eq!(
            system.generators[0].leading_monomial(grevlex_tie_break),
            x0_21,
            "the reverse tie-break must pick the other side of the same tie"
        );
    }

    /// `D_I = 9261` at `r = 5`, enumerated from the weighted leading ideal.
    ///
    /// The paper's closed form `(6α+3)(α(2α+1))^{r−3}` gives 9261, the fixture's generator
    /// reports 9261 from `α_0 · D_H`, and Singular's `vdim` independently agreed
    /// (`docs/research/griffin-freelunch.md` §3.1). This computes it a fourth way, through
    /// Zeebra's own standard-monomial enumeration under the weighted order — which is only
    /// correct if the weighted order is the right one.
    #[test]
    fn test_the_r5_quotient_dimension_is_9261() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        let order = system.order().unwrap();
        let quotient = QuotientBasis::new(&system.generators, order, 100_000).unwrap();
        assert_eq!(system.quotient_dimension, 9261);
        assert_eq!(quotient.dimension(), 9261);
        // α_0 · D_H with D_H = α^{n−1} = 9, i.e. the paper's factorisation of the same number.
        assert_eq!(system.alpha0 as usize * 9, 9261);
    }

    /// `D_I = 441` at `r = 4`, the second rung of the same ladder.
    #[test]
    fn test_the_r4_quotient_dimension_is_441() {
        let system = FreeLunchSystem::<2, F>::parse(FREELUNCH_R4).unwrap();
        let order = system.order().unwrap();
        let quotient = QuotientBasis::new(&system.generators, order, 100_000).unwrap();
        assert_eq!(system.quotient_dimension, 441);
        assert_eq!(quotient.dimension(), 441);
        assert_eq!(system.alpha0 as usize * 3, 441);
    }

    /// The whole `r = 5` system vanishes at both published CICO witnesses.
    ///
    /// The faithfulness gate, and the one check here that no amount of internal consistency could
    /// substitute for: these two `x_0` values are printed in the FreeLunch appendix.
    #[test]
    fn test_the_r5_system_vanishes_at_both_published_witnesses() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        assert_eq!(system.witnesses.len(), 2, "both published r = 5 witnesses");
        assert_eq!(
            system.witnesses[0][0],
            F::new(3490692521816093),
            "the first published witness's x_0"
        );
        assert_eq!(
            system.witnesses[1][0],
            F::new(20508905520120247),
            "the second published witness's x_0"
        );
        for witness in &system.witnesses {
            for (i, generator) in system.generators.iter().enumerate() {
                assert!(
                    generator.eval(witness).is_zero(),
                    "generator {} does not vanish at the published witness",
                    i
                );
            }
        }
    }

    /// A witness is a point of the variety, so it reduces to zero through the normal form too.
    ///
    /// Reducing `g` against `{p_1, p_2}` leaves a polynomial in `x_0` alone — the eliminant the
    /// attack's `polyDet` produces by a different route — and it still vanishes at both
    /// witnesses. This is the weighted normal form against a caller-supplied basis doing the one
    /// job the attack needs it for, checked against published data.
    #[test]
    fn test_reducing_g_by_the_modelling_equations_keeps_the_witnesses() {
        let system = FreeLunchSystem::<3, F>::parse(FREELUNCH_R5).unwrap();
        let order = system.order().unwrap();
        let modelling = &system.generators[..2];
        let reduced = system.generators[2]
            .normal_form_modulo(modelling, order)
            .unwrap();
        assert!(!reduced.is_zero(), "g is not in the ideal of the p_i alone");
        for witness in &system.witnesses {
            assert!(
                reduced.eval(witness).is_zero(),
                "the reduced g does not vanish at a published witness"
            );
        }
    }

    /// The fixture reader refuses a fixture parsed at the wrong variable count or field.
    #[test]
    fn test_the_fixture_reader_refuses_a_mismatch() {
        use super::FixtureError;
        assert_eq!(
            FreeLunchSystem::<2, F>::parse(FREELUNCH_R5).unwrap_err(),
            FixtureError::VariableCount {
                fixture: 3,
                expected: 2
            }
        );
        assert_eq!(
            FreeLunchSystem::<3, PrimeFieldElement64<13>>::parse(FREELUNCH_R5).unwrap_err(),
            FixtureError::Characteristic {
                fixture: FREELUNCH_PRIME,
                field: Some(13)
            }
        );
    }
}
